{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Ketoconazole, an azole antifungal sharing the imidazole and dichlorophenyl ether pharmacophore with the query, has a measured mean oral bioavailability of approximately 75% in healthy volunteers after a 200 mg dose, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Clotrimazole, another imidazole antifungal, was reported to have low oral bioavailability in humans, providing a contradictory example; however, its triphenylmethane structure and very poor absorption limit direct transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "Y-20811, an imidazole-containing drug, showed absolute oral bioavailability of 0.72–0.81 in humans, indicating good absorption and supporting F ≥ 20% for imidazole-based compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Triazolam, an azole-containing drug, has an oral bioavailability of 60% in healthy subjects, supporting the likelihood that azole-containing lipophilic drugs can exceed the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a miconazole-like imidazole antifungal. The closest structural analogue, ketoconazole, has high oral bioavailability (~75%), and multiple other azole/imidazole-containing drugs show F ≥ 20%. Clotrimazole is a low-bioavailability counterexample, but its very poor absorption and lower structural transferability reduce its weight. The physicochemical prior is mixed and does not affirmatively establish F < 20%. Overall, the evidence supports high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability record for miconazole/query was provided.",
    "Closest analogues have Morgan similarity below 0.3, limiting quantitative transferability.",
    "Solubility and first-pass metabolism data specific to the query are unavailable."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

